"""Strict, deterministic conversion of provider candidates to Phase 1 models."""

from __future__ import annotations

import math
import re
import unicodedata

from virvision.scene import BBox, DetectedObject, DetectedText, VisualScene

from .base import RawObject, RawText


def _finite(value, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be numeric")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return value


def _confidence(value, name: str) -> float:
    value = _finite(value, name)
    if not 0 <= value <= 1:
        raise ValueError(f"{name} must be within [0, 1]")
    return value


def _pixel_box(values, width: int, height: int, name: str) -> tuple[float, float, float, float]:
    if not isinstance(values, (tuple, list)) or len(values) != 4:
        raise ValueError(f"{name} must contain x1,y1,x2,y2")
    x1, y1, x2, y2 = (_finite(value, name) for value in values)
    x1, x2 = min(max(x1, 0), width), min(max(x2, 0), width)
    y1, y2 = min(max(y1, 0), height), min(max(y2, 0), height)
    if x1 > x2 or y1 > y2:
        raise ValueError(f"{name} must satisfy x1 <= x2 and y1 <= y2")
    return x1, y1, x2, y2


def _normalized_box(values, width: int, height: int, name: str) -> BBox:
    x1, y1, x2, y2 = _pixel_box(values, width, height, name)
    return BBox(x1 / width, y1 / height, x2 / width, y2 / height)


def _spatial_key(box: BBox, tie: tuple = ()) -> tuple:
    return ((box.y1 + box.y2) / 2, (box.x1 + box.x2) / 2, *tie)


def normalize_objects(
    candidates: tuple[RawObject, ...] | list[RawObject],
    width: int,
    height: int,
    *,
    max_objects: int | None = None,
) -> tuple[DetectedObject, ...]:
    if width <= 0 or height <= 0:
        raise ValueError("image dimensions must be positive")
    if max_objects is not None and (
        isinstance(max_objects, bool) or not isinstance(max_objects, int) or max_objects < 1
    ):
        raise ValueError("max_objects must be a positive integer or None")
    rows = []
    for index, item in enumerate(candidates):
        if not isinstance(item, RawObject):
            raise ValueError(f"object candidate {index} has an invalid type")
        label = item.label.strip() if isinstance(item.label, str) else ""
        if not label:
            raise ValueError(f"object candidate {index} has an empty class label")
        confidence = _confidence(item.confidence, f"object candidate {index} confidence")
        box = _normalized_box(item.bbox_xyxy, width, height, f"object candidate {index} bbox")
        rows.append((box, label, confidence, index))
    rows.sort(key=lambda row: _spatial_key(row[0], (row[1].casefold(), -row[2], row[3])))
    if max_objects is not None:
        rows = rows[:max_objects]
    return tuple(
        DetectedObject(f"O{index}", label, box, confidence)
        for index, (box, label, confidence, _) in enumerate(rows, 1)
    )


def _text_key(text: str) -> str:
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", text).casefold()).strip()


def _iou(a: BBox, b: BBox) -> float:
    left, top = max(a.x1, b.x1), max(a.y1, b.y1)
    right, bottom = min(a.x2, b.x2), min(a.y2, b.y2)
    intersection = max(0.0, right - left) * max(0.0, bottom - top)
    area_a = (a.x2 - a.x1) * (a.y2 - a.y1)
    area_b = (b.x2 - b.x1) * (b.y2 - b.y1)
    union = area_a + area_b - intersection
    return intersection / union if union > 0 else 1.0 if a == b else 0.0


def normalize_texts(
    candidates: tuple[RawText, ...] | list[RawText],
    width: int,
    height: int,
    *,
    dedup_iou: float = 0.80,
) -> tuple[DetectedText, ...]:
    threshold = _confidence(dedup_iou, "dedup_iou")
    rows = []
    for index, item in enumerate(candidates):
        if not isinstance(item, RawText):
            raise ValueError(f"OCR candidate {index} has an invalid type")
        if not isinstance(item.text, str) or not item.text.strip():
            continue
        if not isinstance(item.polygon, (tuple, list)) or len(item.polygon) < 2:
            raise ValueError(f"OCR candidate {index} polygon needs at least two points")
        points = []
        for point in item.polygon:
            if not isinstance(point, (tuple, list)) or len(point) != 2:
                raise ValueError(f"OCR candidate {index} contains an invalid point")
            points.append((_finite(point[0], "OCR x"), _finite(point[1], "OCR y")))
        box = _normalized_box(
            (
                min(p[0] for p in points),
                min(p[1] for p in points),
                max(p[0] for p in points),
                max(p[1] for p in points),
            ),
            width,
            height,
            f"OCR candidate {index} bbox",
        )
        confidence = _confidence(item.confidence, f"OCR candidate {index} confidence")
        language = (
            item.language if isinstance(item.language, str) and item.language.strip() else "unknown"
        )
        rows.append((box, item.text, confidence, language, index))
    # Highest-confidence exact-normalized duplicate wins; spatial ordering happens after dedup.
    retained = []
    for row in sorted(rows, key=lambda value: (-value[2], value[4])):
        box, text, *_ = row
        if any(
            _text_key(text) == _text_key(existing[1]) and _iou(box, existing[0]) >= threshold
            for existing in retained
        ):
            continue
        retained.append(row)
    retained.sort(key=lambda row: _spatial_key(row[0], (_text_key(row[1]), -row[2], row[4])))
    return tuple(
        DetectedText(f"T{index}", text, box, confidence, language)
        for index, (box, text, confidence, language, _) in enumerate(retained, 1)
    )


def fuse_scene(
    width: int,
    height: int,
    objects: tuple[DetectedObject, ...],
    texts: tuple[DetectedText, ...],
) -> VisualScene:
    return VisualScene(width=width, height=height, objects=objects, texts=texts)
